import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.DdtnLau3.js";const k=JSON.parse('{"title":"Web Development","description":"","frontmatter":{},"headers":[],"relativePath":"guide/web-development.md","filePath":"guide/web-development.md"}'),n={name:"guide/web-development.md"};function r(o,e,p,d,l,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="web-development" tabindex="-1">Web Development <a class="header-anchor" href="#web-development" aria-label="Permalink to &quot;Web Development&quot;">​</a></h1><p>New applications default to <strong>Python 3.13 + NiceGUI + SQLite</strong>. Standard packages and browser resources ship with the fixed base image, without per-application Node installation, npm or a separate frontend build. The Agent edits the shared Work workspace; Core runs the application in a separate Service.</p><p>After <a href="/piwork/guide/quick-start.html">Quick Start</a>, create a Work in the workbench and describe the task in Chat, such as “Build a task board, persist its data, deploy it as a Service and verify the running result.” Preview or open the application from its Service entry. Maintain existing applications through targeted edits without initializing them again.</p><p>The older FastAPI/React image remains a historical artifact; existing applications are not converted automatically.</p><h2 id="availability-and-identity" tabindex="-1">Availability and identity <a class="header-anchor" href="#availability-and-identity" aria-label="Permalink to &quot;Availability and identity&quot;">​</a></h2><p>The current source defines environment contract <strong>2</strong>, version series <strong>0.2.0</strong>, Python <strong>3.13.16</strong>, NiceGUI <strong>3.18.0</strong>, pip <strong>26.2.1</strong>, and sqlite3 CLI <strong>3.40.1-2+deb12u2</strong>, initially for Linux amd64. Exact standard dependencies are in <a href="https://github.com/pphboy/piwork/blob/main/deploy/images/web-base/requirements.lock" target="_blank" rel="noreferrer">requirements.lock</a>; <a href="https://github.com/pphboy/piwork/blob/main/deploy/images/web-base/environment.json" target="_blank" rel="noreferrer">environment.json</a> fixes the upstream Python image. The built read-only manifest also records installed packages and the actual input hash.</p><p><strong>Published and anonymously verified.</strong> <code>docker.io/pphboy/piwork-web-base:0.2.0-5818e1de7bb5-6b6f6f8bbf62-dirty@sha256:c85c9928549f5b6a58dd519bbf1840fe83e52b9da22eaae556f7aca64b448098</code> is the fixed Linux amd64, contract-2 base. <a href="https://github.com/pphboy/piwork/blob/main/deploy/images/web-base/release.json" target="_blank" rel="noreferrer">release.json</a> records the actual build commit/dirty flag, input hash, image ID and registry digest; the bundled brain uses this verified reference. <code>dist/web-base/candidate.json</code> retains the local build identity. The previous FastAPI/React release remains in <a href="https://github.com/pphboy/piwork/blob/main/deploy/images/web-base/releases/fastapi-react-0.1.0.json" target="_blank" rel="noreferrer">the historical release record</a>.</p><h2 id="use-in-a-work" tabindex="-1">Use in a Work <a class="header-anchor" href="#use-in-a-work" aria-label="Permalink to &quot;Use in a Work&quot;">​</a></h2><p>For a new Pi-managed application, invoke <code>node &lt;loaded-skill-directory&gt;/initialize.mjs --template web-app --name &lt;service-name&gt;</code> through authorized <strong>Agent bash</strong>. <code>workstation</code> selects the feedback/export example. The initializer rejects every existing target before writes, creates SPEC.md first and copies an editable application into <code>apps/&lt;service-name&gt;</code>. Maintain existing applications with targeted edits; do not initialize them again.</p><p>Use an actual verified image reference, explicit read/write workspace grant, command <code>/usr/local/bin/piwork-web</code>, args <code>[&quot;run&quot;, &quot;--app&quot;, &quot;/var/data/workspace/apps/&lt;service-name&gt;&quot;]</code>, TCP port 8080 named <code>web</code>, and HTTP <code>/health</code> readiness. Source, checks and temporary files stay under the app; business data stays in <code>data/&lt;service-name&gt;</code>. Core injects interaction identity and CA at <code>/etc/piwork/interaction</code>; they never enter browser JavaScript or source.</p><p>The same base can run an ordinary NiceGUI script with its own <code>python app.py</code> command, or be extended with <code>FROM</code>. It contains no Todo/review business application and requires no Pi identity for an ordinary script. Pi-managed templates use the existing Service protocol.</p><h2 id="commands-and-adopting-changes" tabindex="-1">Commands and adopting changes <a class="header-anchor" href="#commands-and-adopting-changes" aria-label="Permalink to &quot;Commands and adopting changes&quot;">​</a></h2><p>Inside the <strong>Service base</strong>, in the application directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">piwork-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">piwork-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">piwork-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">piwork-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">piwork-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><code>prepare</code> selects the standard or prepared extra environment. <code>check</code> runs Python source/application checks. <code>run</code> prepares, runs missing/mismatched checks and serves; identical input reuses valid checks on restart. <code>serve</code> refuses unmatched checks. <code>dev</code> explicitly enables Python reload. There is no separate frontend build command.</p><p>After editing, Pi completes necessary checks and the original Service update/restart, then verifies the actually running codeVersion and business result. The template adopts ready versions automatically, restores its supported nonsecret Todo-title draft and current path, and re-reads shared business state. Failed checks, temporary disconnection and unchanged versions do not cause reload loops. These actions do not Apply brain/Work configuration.</p><p>The application exposes safe versions at <code>/api/runtime-version</code>: codeVersion binds source/configuration, extra dependency locks and the actual base environment; frontendVersion binds Python page/resources, locks and environment. A writable marker does not change the process&#39;s loaded version.</p><p>The default page inputs are <code>app.py</code>, <code>ui.py</code>, <code>page-client.js</code> and <code>style.css</code> when present. Extend them with app-relative helper/resource paths in <code>page-files.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;files&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pages/header.py&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;assets/theme.css&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}</span></span></code></pre></div><p>Maintain this list and the application Spec when splitting pages or adding/removing resources. Effective paths are sorted and deduplicated; changing a listed file or the effective set changes frontendVersion, while independent business changes leave it stable. Missing/invalid files, escaping paths and symlinks fail checks/startup. Keep business modules, data, caches and dependency environments out of the list. Existing apps without a manifest retain the default page inputs.</p><h2 id="additional-python-packages" tabindex="-1">Additional Python packages <a class="header-anchor" href="#additional-python-packages" aria-label="Permalink to &quot;Additional Python packages&quot;">​</a></h2><p>Put exact <strong>additional</strong> pins in the app&#39;s <code>requirements.in</code>, for example <code>package-name==1.2.3</code>, or a local wheel path below the app. Explicit preparation may acquire compatible packages from a reachable registry:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">piwork-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-deps</span></span></code></pre></div><p>For Agent-driven installation, Pi writes the declaration and uses the existing Service command/Operation with <code>run --install-deps</code>; Agent bash itself has no Python/pip, and does not use Docker exec/build. Once prepared, the same input never re-downloads, including when the Service definition retains that flag.</p><p>Extra packages are installed with pip into a writable, versioned <code>.deps/</code> environment which inherits standard packages. <code>requirements.lock</code>, validated wheels, and the active environment record are retained. Checks, the application and installed console scripts use the selected interpreter. The installer does not upgrade fixed base packages; conflicts, unavailable system libraries, download or integrity failures are reported and preserve the previous valid environment and data. Standard applications create no full venv/node_modules. Removing an extra environment or moving an app allows exact offline reconstruction from retained materials, with the matching base available.</p><p>System libraries or changes to the base package versions belong in a derived image. At build time, a downstream Dockerfile can switch to root to install fixed dependencies, then return to <code>USER 10001:10001</code>. Applications using the version adapter must bind their derived environment manifest to their actual build inputs; do not advertise a modified environment using the unchanged base manifest.</p><p>Build with <code>docker build --build-arg NICEGUI_BASE=&lt;verified-fixed-reference&gt; -t my-nicegui-app:local .</code>, providing your own app and complete hashed requirements.lock. A verified local candidate is valid for this local development build; use a published fixed digest for distribution.</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ARG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NICEGUI_BASE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${NICEGUI_BASE}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 0:0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> requirements.lock /opt/my-app/requirements.lock</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> python -m pip install --require-hashes -r /opt/my-app/requirements.lock</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.py /opt/my-app/app.py</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 10001:10001</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;python&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/my-app/app.py&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="persistence-identity-and-sqlite3" tabindex="-1">Persistence, identity and sqlite3 <a class="header-anchor" href="#persistence-identity-and-sqlite3" aria-label="Permalink to &quot;Persistence, identity and sqlite3&quot;">​</a></h2><p>The runtime uses UID/GID <strong>10001:10001</strong>, a read-only root filesystem and only its granted workspace for writable HOME/TMPDIR/cache/dependencies. Stop/Start and Service replacement retain source, locks and data. Full Work export/import retains extra installation materials; import produces a stopped Work, and the user explicitly starts it. The fixed base image must be available on the destination. Existing Work packages/applications/images are not automatically converted.</p><p>Both Agent and the base provide the real sqlite3 CLI. AI bash runs in Agent; a Service-only command is not evidence that Agent can execute it. Ordinary business changes still use the named Query/Action contract.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/data/workspace/data/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">service-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/workstation.sqlite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;SELECT name FROM sqlite_master WHERE type=&quot;table&quot;;&#39;</span></span></code></pre></div><p>Application Services have no Piwork memory cap/reservation; deprecated memoryBytes is compatibility history, not an available budget. CPU and count admission still apply. See <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/core-service-startup/spec.md" target="_blank" rel="noreferrer">operations</a>.</p><h2 id="maintain-validate-and-publish" tabindex="-1">Maintain, validate and publish <a class="header-anchor" href="#maintain-validate-and-publish" aria-label="Permalink to &quot;Maintain, validate and publish&quot;">​</a></h2><p>The authority is this repository directory. Brain templates/references consume it; <code>dist/web-base/</code> contains ignored local outputs; DockerHub holds published artifacts. Developer image checks require Docker Engine/CLI and the repository&#39;s Node tooling; product hosts gain no Python/Node/sqlite3 dependency.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/lock-web-base.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web-base-image</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-web-base-tools.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-web-base.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-web-base.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/web-base/candidate.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-web-base-dependencies.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-web-base-core.mjs</span></span></code></pre></div><p>Real Core/SDK/browser checks also need the compatible acceptance Agent/helper images and built Go programs described in <a href="https://github.com/pphboy/piwork/blob/main/AGENTS.md#%E6%9E%84%E5%BB%BA%E4%B8%8E%E9%AA%8C%E8%AF%81" target="_blank" rel="noreferrer">testing</a>. Tests use unique installation/fixture labels and only clean their own resources. Preparation/start/restart, workspace/snapshot sizes and complete sharing are measured separately; a timeout budget is not a measured performance result.</p><p>Local build/validation does not push. Publication uses <code>scripts/publish-web-base.mjs</code> only after explicit release authorization, validates the exact current candidate and evidence, rejects conflicting remote tags, and verifies anonymous digest pull/run before updating the formal brain reference. Old commit/dirty/input/digest identities remain unchanged.</p>`,38)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
